    private void filter(){
        if(list==null)return;shown=new ArrayList<>();groups.clear();groupCounts.clear();groupCovers.clear();String q=MusicLogic.normalize(query);Set<String> favorites=store.favorites();List<String> playlist=section.equals("Playlists")&&group!=null?store.playlist(group):null;
        List<Track> source=category.equals("Recentes")&&section.equals("Biblioteca")?store.tracks("history"):library;
        for(Track t:source){
            if(section.equals("Favoritos")&&!favorites.contains(t.uri))continue;
            if(playlist!=null&&!playlist.contains(t.uri))continue;
            if(section.equals("Biblioteca")&&category.equals("Vídeos")&&!t.video)continue;
            if(section.equals("Biblioteca")&&!category.equals("Vídeos")&&!category.equals("Recentes")&&t.video)continue;
            if(group!=null&&section.equals("Biblioteca")&&!groupName(t).equals(group))continue;
            if(!MusicLogic.normalize(t.title+" "+t.artist+" "+t.album+" "+t.folder).contains(q))continue;shown.add(t);
        }
        if(playlist!=null)shown.sort(Comparator.comparingInt(t->playlist.indexOf(t.uri)));
        else if(!category.equals("Recentes")){
            int sort=store.prefs.getInt("sort",0);Comparator<Track> cmp=sort==1?Comparator.comparingLong((Track t)->t.added).reversed():sort==2?Comparator.comparing(t->MusicLogic.normalize(t.artist)):sort==3?Comparator.comparingLong((Track t)->t.duration).reversed():Comparator.comparing(t->MusicLogic.normalize(t.title));shown.sort(cmp);
        }
        if(section.equals("Biblioteca")&&group==null&&Arrays.asList("Álbuns","Artistas","Pastas").contains(category)){
            TreeSet<String> names=new TreeSet<>(String.CASE_INSENSITIVE_ORDER);for(Track t:shown){String key=groupName(t);names.add(key);groupCounts.put(key,groupCounts.getOrDefault(key,0)+1);if(!groupCovers.containsKey(key))groupCovers.put(key,t);}groups.addAll(names);
        }
        boolean collection=section.equals("Playlists")||section.equals("Favoritos")||category.equals("Recentes");
        emptyTitle.setText(!q.isEmpty()?"Nenhum resultado":collection?"Sua coleção começa aqui":"Um espaço para o seu som");
        emptyHelp.setText(!q.isEmpty()?"Tente outro título, artista ou álbum.":collection?"Use o menu das músicas para organizar suas faixas. Seu histórico aparece conforme você escuta.":"Libere sua biblioteca ou escolha arquivos locais.\nSuas músicas não saem do aparelho.");
        emptyAccess.setVisibility(q.isEmpty()&&!collection&&!Library.permission(this,category.equals("Vídeos"))?View.VISIBLE:View.GONE);emptyFiles.setVisibility(q.isEmpty()&&!collection?View.VISIBLE:View.GONE);
        count.setText(scanning?"ATUALIZANDO…":groups.isEmpty()?shown.size()+(category.equals("Vídeos")?" vídeos":" músicas"):groups.size()+" coleções");adapter.notifyDataSetChanged();
    }
    private String groupName(Track t){return category.equals("Álbuns")?t.album:category.equals("Artistas")?t.artist:t.folder;}
