    private final class TrackAdapter extends BaseAdapter{
        public int getCount(){return groups.isEmpty()?shown.size():groups.size();}public Object getItem(int p){return groups.isEmpty()?shown.get(p):groups.get(p);}public long getItemId(int p){return p;}
        public View getView(int position,View reused,ViewGroup parent){
            TrackRow h=reused!=null&&reused.getTag() instanceof TrackRow?(TrackRow)reused.getTag():new TrackRow();
            boolean grouping=!groups.isEmpty();Track track=grouping?groupCovers.get(groups.get(position)):shown.get(position);String name=grouping?groups.get(position):track.title;
            h.art.track(track);h.title.setText(name);h.detail.setText(grouping?groupCounts.getOrDefault(name,0)+" faixas":track.artist);
            h.more.setVisibility(grouping?View.GONE:View.VISIBLE);h.more.setContentDescription("Opções de "+name);h.more.setOnClickListener(v->{if(track!=null)trackMenu(track);});
            h.row.setOnClickListener(v->{if(grouping){group=name;render();}else play(shown,position);});h.row.setOnLongClickListener(v->{if(!grouping){trackMenu(track);return true;}return false;});return h.row;
        }
    }
    private void sortDialog(){new VolumeDialogBuilder(this).setTitle("Ordenar por").setSingleChoiceItems(new String[]{"Título","Adicionadas recentemente","Artista","Duração"},store.prefs.getInt("sort",0),(d,w)->{store.prefs.edit().putInt("sort",w).apply();filter();d.dismiss();}).show();}
    private void requestLibrary(){store.prefs.edit().putBoolean("audio_permission_requested",true).apply();ArrayList<String> perms=new ArrayList<>();if(Build.VERSION.SDK_INT>=33){perms.add(Manifest.permission.READ_MEDIA_AUDIO);if(category.equals("Vídeos")){perms.add(Manifest.permission.READ_MEDIA_VIDEO);if(Build.VERSION.SDK_INT>=34)perms.add(Manifest.permission.READ_MEDIA_VISUAL_USER_SELECTED);}}else perms.add(Manifest.permission.READ_EXTERNAL_STORAGE);requestPermissions(perms.toArray(new String[0]),40);}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==40)scan();}
    private void scan(){if(isDestroyed())return;if(scanning){scanAgain=true;return;}scanning=true;filter();io.execute(()->{try{List<Track> result=Library.scan(this,store);runOnUiThread(()->{if(isDestroyed())return;library=result;scanning=false;loaded=true;filter();if(scanAgain){scanAgain=false;scan();}});}catch(Exception e){runOnUiThread(()->{scanning=false;filter();toast("Não foi possível ler a biblioteca. Tente escolher os arquivos manualmente.");});}});}
    private void pickMedia(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/*","video/*"}).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true).addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,50);}
    private void importTrack(Uri uri,boolean play){
        io.execute(()->{try{Track t=Library.importUri(this,uri);store.addImport(t);runOnUiThread(()->{if(isDestroyed())return;library.removeIf(x->x.uri.equals(t.uri));library.add(t);filter();if(play){if(controller==null)pendingOpen=t.uri;else play(Collections.singletonList(t),0);}else toast("Adicionado: "+t.title);});}catch(Exception e){runOnUiThread(()->toast("Não foi possível abrir o arquivo selecionado"));}});
    }
    private void play(List<Track> tracks,int index){
        if(controller==null){toast("Conectando ao player. Tente novamente em instantes.");return;}if(tracks.isEmpty())return;
        List<MediaItem> items=new ArrayList<>();for(Track t:tracks)items.add(t.item());controller.setMediaItems(items,index,0);controller.prepare();controller.play();hideKeyboard();updatePlayback();if(tracks.get(index).video)showPlayer();
    }
    private void hideKeyboard(){View f=getCurrentFocus();if(f!=null){((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(f.getWindowToken(),0);f.clearFocus();}}
    private void togglePlay(){if(controller==null){toast("Conectando ao player…");return;}if(controller.isPlaying())controller.pause();else if(controller.getMediaItemCount()>0){if(controller.getPlaybackState()==Player.STATE_IDLE)controller.prepare();if(controller.getPlaybackState()==Player.STATE_ENDED)controller.seekToDefaultPosition();controller.play();}else if(!shown.isEmpty())play(shown,0);else toast("Adicione músicas à biblioteca para começar");}
    private Track current(){return controller==null||controller.getCurrentMediaItem()==null?null:Track.item(controller.getCurrentMediaItem());}
    private void trackMenu(Track t){
        ArrayList<String> actions=new ArrayList<>(Arrays.asList("Tocar agora","Tocar a seguir","Adicionar à fila",store.favorites().contains(t.uri)?"Remover dos favoritos":"Adicionar aos favoritos","Adicionar a uma playlist","Compartilhar arquivo","Detalhes"));
        actions.add("Escolher capa");if(section.equals("Playlists")&&group!=null)actions.add("Remover desta playlist");
        new VolumeDialogBuilder(this).setTitle(t.title).setItems(actions.toArray(new String[0]),(d,w)->{
            switch(w){case 0:play(Collections.singletonList(t),0);break;case 1:case 2:if(controller!=null){int at=w==1?Math.min(controller.getMediaItemCount(),controller.getCurrentMediaItemIndex()+1):controller.getMediaItemCount();controller.addMediaItem(Math.max(0,at),t.item());toast("Adicionada à fila");}break;
                case 3:store.favorite(t.uri);filter();updatePlayback();break;case 4:addPlaylist(t);break;case 5:share(t);break;
                case 6:new VolumeDialogBuilder(this).setTitle("Detalhes").setMessage(t.title+"\n"+t.artist+"\n"+t.album+"\n\n"+t.folder+"\n"+MusicLogic.time(t.duration)+"\n\n"+t.uri).setPositiveButton("Fechar",null).show();break;
                case 7:pendingArtwork=t.uri;startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE),54);break;case 8:store.removeFromPlaylist(group,t.uri);filter();break;
            }
        }).show();
    }
    private void share(Track t){try{Intent i=new Intent(Intent.ACTION_SEND).setType(t.video?"video/*":"audio/*").putExtra(Intent.EXTRA_STREAM,Uri.parse(t.uri)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"Compartilhar arquivo"));}catch(Exception e){toast("Este arquivo não pode ser compartilhado");}}
