    private void updatePlayback(){
        if(controller==null)return;Track t=current();boolean playing=controller.isPlaying();miniPlay.setText(playing?"Ⅱ":"▶");
        if(t==null){label(miniTitle,"Escolha sua primeira música");label(miniSub,"Tudo fica no seu aparelho");if(playerDialog!=null)playerDialog.dismiss();return;}if(!t.title.contentEquals(miniTitle.getText()))label(miniTitle,t.title);if(!t.artist.contentEquals(miniSub.getText()))label(miniSub,t.artist);if(miniProgress!=null)miniProgress.setProgress(controller.getDuration()>0?(int)(controller.getCurrentPosition()*1000/controller.getDuration()):0);miniArt.track(t);if(playerTitle==null)return;
        label(playerTitle,t.title);label(playerArtist,t.artist);playerPlay.setText(playing?"Ⅱ":"▶");favorite.setText(store.favorites().contains(t.uri)?"♥︎":"♡");favorite.setTextColor(store.favorites().contains(t.uri)?BLUE:INK);
        shuffle.setTextColor(controller.getShuffleModeEnabled()?BLUE:MUTED);repeat.setText(controller.getRepeatMode()==Player.REPEAT_MODE_ONE?"↻¹":"↻");repeat.setTextColor(controller.getRepeatMode()==Player.REPEAT_MODE_OFF?MUTED:BLUE);
        long duration=controller.getDuration();if(duration<0)duration=t.duration;long position=controller.getCurrentPosition();if(!dragging){seek.setProgress(duration<=0?0:(int)(position*1000/duration));label(elapsed,MusicLogic.time(position));}label(total,MusicLogic.time(duration));
        String status=controller.getPlaybackState()==Player.STATE_BUFFERING?"Preparando arquivo…":controller.getPlayerError()!=null?"Arquivo indisponível ou formato não suportado":"";
        if(PlaybackService.active!=null&&PlaybackService.active.timerRemaining()>0)status+=" · pausa em "+MusicLogic.time(PlaybackService.active.timerRemaining());if(controller.getPlaybackParameters().speed!=1f)status+="  "+controller.getPlaybackParameters().speed+"×";label(playerStatus,status);playerStatus.setVisibility(status.isEmpty()?View.GONE:View.VISIBLE);
        if(visualTrack==null||!visualTrack.uri.equals(t.uri)){animateTrack(visualTrack,t);visualTrack=t;}else cover.track(t);if(!displayedUri.equals(t.uri)){displayedUri=t.uri;video.setVisibility(t.video?View.VISIBLE:View.GONE);cover.setVisibility(t.video?View.GONE:View.VISIBLE);if(playerDialog!=null&&playerDialog.getWindow()!=null){if(t.video)playerDialog.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else playerDialog.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}String raw=store.lyric(t.uri);lyricLines=MusicLogic.lyrics(raw);lastLyric=-2;lyricText.setTextColor(MUTED);if(lyricLines.isEmpty())lyricText.setText(raw.isEmpty()?"Adicione uma letra local para acompanhar.":raw);}
        if(!lyricLines.isEmpty()){int index=MusicLogic.lyricIndex(lyricLines,position);if(index!=lastLyric){lastLyric=index;StringBuilder lines=new StringBuilder();int first=Math.max(0,index);for(int i=first;i<Math.min(first+3,lyricLines.size());i++)lines.append(lyricLines.get(i).text).append("\n");lyricText.setText(lines.toString().trim());lyricText.setTextColor(BLUE);}}
    }
