    private void installMiniSwipe(View target){
        target.setOnTouchListener(new View.OnTouchListener(){float x,y;boolean moved;
            public boolean onTouch(View v,MotionEvent e){switch(e.getActionMasked()){
                case MotionEvent.ACTION_DOWN:x=e.getRawX();y=e.getRawY();moved=false;return true;
                case MotionEvent.ACTION_MOVE:if(y-e.getRawY()>dp(8)&&Math.abs(e.getRawY()-y)>Math.abs(e.getRawX()-x)){moved=true;v.setTranslationY(Math.max(-dp(28),(e.getRawY()-y)*.3f));}return true;
                case MotionEvent.ACTION_UP:v.animate().translationY(0).setDuration(MotionCurves.duration(300)).start();if(moved&&y-e.getRawY()>dp(19.2f))showPlayer();else if(!moved)v.performClick();return true;
                case MotionEvent.ACTION_CANCEL:v.animate().translationY(0).setDuration(MotionCurves.duration(300)).start();return true;
            }return false;}
        });
    }
