        quickLevel.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){adjustingQuickVolume=true;handler.removeCallbacks(hideQuickVolume);}public void onStopTrackingTouch(SeekBar s){adjustingQuickVolume=false;scheduleQuickHide();}public void onProgressChanged(SeekBar s,int n,boolean user){if(user){try{audio.setStreamVolume(android.media.AudioManager.STREAM_MUSIC,n,0);}catch(SecurityException ignored){}syncQuickVolume();}}});
